  'inicio.hero_gradient' => 'el recorrido escolar',
  'inicio.hero_suffix' => 'de tu hijo',
  'inicio.hero_desc' => 'Accedé a notas, asistencia, comunicados y mucho más desde cualquier dispositivo. Conectando a las familias con la vida escolar en tiempo real.',
  'inicio.everything_in_one_place' => 'Todo lo que necesitás saber de tu hijo en un solo lugar',
  'inicio.step2_desc' => 'En este portal solo hace falta el mismo número de documento del responsable, sin contraseña adicional ni registro previo.',
  'inicio.modal_disclaimer' => 'El ingreso debe realizarse exclusivamente con el DNI del responsable registrado. La información mostrada tiene carácter informativo y no oficial.',
