  'inicio.testi1_quote' => '"Antes tenía que llamar al colegio para saber cómo iba mi hijo. Ahora entro al portal y en segundos veo todo."',
  'inicio.testi1_role' => 'Madre de alumno de 4° año',
  'inicio.testi2_quote' => '"El boletín digital es fantástico. Lo descargué directo desde el celular y lo mandé a los abuelos al toque."',
  'inicio.testi2_role' => 'Padre de alumna de 2° año',
