  'inicio.faq2_q' => '¿Mis datos están protegidos?',
  'inicio.faq2_a' => 'Sí. El sistema usa conexión cifrada (HTTPS) y tus datos nunca se comparten con terceros. Podés leer nuestra política de privacidad en la secretaría del colegio.',
  'inicio.faq3_q' => '¿Puedo ver los datos de mis hijos si tengo más de uno?',
  'inicio.faq4_q' => '¿Qué hago si no puedo ingresar?',
  'inicio.faq4_a' => 'Verificá que el DNI sea el mismo que figura como responsable en la ficha del estudiante. Si falta o está mal cargado, pedí la corrección en secretaría.',
  'inicio.faq5_q' => '¿Cuándo se actualizan las notas?',
  'inicio.faq5_a' => 'Las notas se publican en el portal a medida que los docentes las cargan, generalmente dentro de las 48 hs de la evaluación.',
  'inicio.cta_title' => '¿Listo para conectarte con la escuela de tu hijo?',
  'inicio.cta_desc' => 'Ingresá con el DNI del responsable que tiene cargada la institución.',
  'inicio.footer_disclaimer' => 'Los datos sobre calificaciones, asistencia y legajos visualizados a través de este portal digital son de carácter exclusivamente informativo. De acuerdo con las normativas escolares vigentes, la única documentación con validez legal y oficial es aquella firmada y sellada físicamente por las autoridades de la institución o emitida de forma presencial en la secretaría del establecimiento. Ante cualquier discrepancia entre los datos digitales y los registros en soporte físico (libros de actas y matrices), prevalecerán siempre los registros físicos oficiales.',
